<script setup>
import {computed,ref} from 'vue';import {simulateRequirements} from '../sim/models/requirements.mjs';
const seatModel=ref('assigned'),flashSale=ref(false),hold=ref(false),cancellation=ref(false);const r=computed(()=>simulateRequirements({seatModel:seatModel.value,flashSale:flashSale.value,hold:hold.value,cancellation:cancellation.value}));
function bars(n){return '●'.repeat(Math.min(5,n))+'○'.repeat(Math.max(0,5-n))}
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>預約規則</span><div class="sim-segment"><button v-for="(label,id) in {assigned:'指定座位',general:'自由入場',waitlist:'可候補'}" :key="id" :aria-pressed="seatModel===id" @click="seatModel=id">{{label}}</button></div></div><div><span>情境條件</span><div class="sim-segment"><button :aria-pressed="flashSale" @click="flashSale=!flashSale">開賣尖峰</button><button :aria-pressed="hold" @click="hold=!hold">付款前保留</button><button :aria-pressed="cancellation" @click="cancellation=!cancellation">允許取消</button></div></div></div><div class="requirement-rule"><span>目前不能被破壞的規則</span><strong>{{r.rule}}</strong></div><div class="concern-grid"><div v-for="q in r.questions" :key="q.id" :class="['concern-card',{'is-hot':q.level>=3}]"><span>{{q.label}}</span><strong>{{bars(q.level)}}</strong></div></div><div class="sim-consequence"><strong>改的是需求，後面的設計問題也跟著變</strong><p>切換「自由入場 → 指定座位」，再開啟「付款前保留」或「允許取消」。這裡還沒有選 database / queue；先看哪些問題變得更重要。</p></div></section></template>